test("an extra note field is rejected as an unknown field", function () {
  assert.throws(function () {
    code.calculateQuarterlyRebate({ quarterlyPurchases: 60000.00, note: 1 });
  }, /^unknown field: note$/);
});

test("a missing quarterlyPurchases field is rejected as invalid", function () {
  assert.throws(function () {
    code.calculateQuarterlyRebate({});
  }, /^invalid field: quarterlyPurchases$/);
});

test("a string quarterlyPurchases value is rejected as not a finite number", function () {
  assert.throws(function () {
    code.calculateQuarterlyRebate({ quarterlyPurchases: "10000.50" });
  }, /^invalid field: quarterlyPurchases$/);
});
